implementation.source:
mayaSurfaceShaderOutput SplatPixel(
    float4 colorFromGS,
    float3 uvFromGS,
    float4 solidColor,
    float4 diffuseColor,
    float diffuse,
    float noDiscard)
{
    // noDiscard (the wire item) keeps the whole quad: no ellipse test and no noise.
    bool keepAll = noDiscard > 0.5;

    // Outside the unit disk of the quad is outside the ellipse of the splat.
    if (!keepAll && (dot(uvFromGS.xy, uvFromGS.xy) > 1.0 || uvFromGS.z <= 0.0))
        discard;

    // Noise from the quad-local position and a constant seed: no time or screen input.
    uint h = asuint(uvFromGS.x) * 73856093u ^ asuint(uvFromGS.y) * 19349663u ^ 0x5EED5EEDu;
    h ^= h >> 16;
    h *= 0x7feb352du;
    h ^= h >> 15;
    h *= 0x846ca68bu;
    h ^= h >> 16;
    float noise = float(h >> 8) * (1.0 / 16777216.0);

    // Keep the fragment with a probability equal to the opacity.
    if (!keepAll && uvFromGS.z + 1.0e-5 <= noise)
        discard;

    mayaSurfaceShaderOutput result;
    result.outColor = lerp(colorFromGS.rgb, solidColor.rgb, solidColor.a);
    result.outTransparency = float3(0.0, 0.0, 0.0);
    result.outGlowColor = float3(0.0, 0.0, 0.0);
    result.outMatteOpacity = float3(-1.0e+06, -1.0e+06, -1.0e+06);
    return result;
}
